// Adaptive trapezoidal integration with recursive subdivision
double integral = 0.0;
double c = (a + b) / 2.0;
double h = b - a;
double fa = f->eval(a);
double fb = f->eval(b);
double fc = f->eval(c);
double whole = (h / 2.0) * (fa + fb);
double left = (h / 4.0) * (fa + fc);
double right = (h / 4.0) * (fc + fb);
double error = std::abs(whole - (left + right));

if (error <= 3.0 * precision * h / (b - a)) {
    integral = left + right + (left + right - whole) / 3.0;
} else {
    integral = adaptive_trapezoidal(f, a, c, precision / 2.0) +
               adaptive_trapezoidal(f, c, b, precision / 2.0);
}
return integral;

